// Version simplifiée du calcul (sans interpolation des jours manquants) :
// la version de référence est pipeline/run.py.
function parseCsv(texte) {
  const lignes = [];
  let champ = '', ligne = [], guillemets = false;
  for (let i = 0; i < texte.length; i++) {
    const c = texte[i];
    if (guillemets) {
      if (c === '"' && texte[i + 1] === '"') { champ += '"'; i++; }
      else if (c === '"') guillemets = false;
      else champ += c;
    } else if (c === '"') guillemets = true;
    else if (c === ';') { ligne.push(champ); champ = ''; }
    else if (c === '\n') { ligne.push(champ.replace(/\r$/, '')); lignes.push(ligne); ligne = []; champ = ''; }
    else champ += c;
  }
  if (champ || ligne.length) { ligne.push(champ); lignes.push(ligne); }
  const entetes = lignes.shift().map(h => h.replace(/^\uFEFF/, ''));
  return lignes.filter(l => l.length === entetes.length)
    .map(l => Object.fromEntries(entetes.map((h, i) => [h, l[i]])));
}

const lignes = parseCsv($input.first().json.data)
  .map(r => ({ ...r, _t: new Date(r['Horodatage']) }))
  .sort((a, b) => a._t - b._t);
const fin = lignes[lignes.length - 1];
const limite = new Date(fin._t.getTime() - 28 * 86400000);
const debut = [...lignes].reverse().find(r => r._t <= limite);

const num = v => Number(v || 0);
const colonnes = Object.keys(fin);
const colsAca = colonnes.filter(c => /^Nombre d'utilisateurs de l'académie/.test(c));
const perimetre = colonnes.filter(c => /^Nombre d'utilisateurs/.test(c) &&
  (/académie|région académique/.test(c) || /education\.gouv\.fr$/.test(c) || /IGESR/.test(c)));

const academies = colsAca.map(cu => {
  const nom = cu.replace(/^Nombre d'utilisateurs de l'académie (de |d')/, '');
  const cm = cu.replace("Nombre d'utilisateurs", 'Nombre de messages');
  const u = num(fin[cu]);
  const messages28 = num(fin[cm]) - num(debut[cm]);
  return { academie: nom, utilisateurs: u, nouveaux_28j: u - num(debut[cu]),
           vitalite: u ? Math.round(100 * messages28 / u) / 100 : null };
});
const v = academies.map(a => a.vitalite).filter(x => x !== null).sort((a, b) => a - b);
const mediane = v.length % 2 ? v[(v.length - 1) / 2] : (v[v.length / 2 - 1] + v[v.length / 2]) / 2;
const seuil = Math.round(50 * mediane) / 100;
const utilisateursMen = perimetre.reduce((s, c) => s + num(fin[c]), 0);

return [{ json: {
  genere_le: new Date().toISOString(),
  dernier_releve: fin['Horodatage'],
  national: {
    utilisateurs_perimetre_ministere: utilisateursMen,
    penetration_nationale_pct: Math.round(10000 * utilisateursMen / 1218110) / 100,
    atteinte_cible_pct: Math.round(1000 * utilisateursMen / 100000) / 10,
    mediane_vitalite: mediane,
    seuil_vitalite: seuil,
  },
  academies: academies.map(a => ({ ...a, signal: a.vitalite !== null && a.vitalite < seuil })),
} }];
